package com.alpharip.staffmod.cases.evidencecaselinker; import com.google.gson.*;import java.io.*;import java.util.*; public final class EvidenceLinkStorage {private final File file;public EvidenceLinkStorage(File f){file=f;}public List<EvidenceLink> load(){List<EvidenceLink> o=new ArrayList<EvidenceLink>();if(file==null||!file.isFile())return o;try{for(JsonElement e:new JsonParser().parse(new FileReader(file)).getAsJsonArray()){JsonObject x=e.getAsJsonObject();o.add(new EvidenceLink(x.get("reference").getAsString(),x.get("caseId").getAsString(),x.get("note").getAsString(),x.get("createdAt").getAsLong()));}}catch(Exception e){System.out.println("[AlphaClient] Evidence link load failed: "+e.getMessage());}return o;}public boolean save(List<EvidenceLink> links){if(file==null)return false;File p=file.getParentFile();if(p!=null&&!p.exists()&&!p.mkdirs())return false;JsonArray a=new JsonArray();for(EvidenceLink e:links){JsonObject x=new JsonObject();x.addProperty("reference",e.getEvidenceReference());x.addProperty("caseId",e.getCaseId());x.addProperty("note",e.getNote());x.addProperty("createdAt",e.getCreatedAt());a.add(x);}try{FileWriter w=new FileWriter(file);try{w.write(a.toString());}finally{w.close();}return true;}catch(Exception e){return false;}}}